export interface IConfigurableOption<T extends AbstractControl> {
  control: T;
}

@Component({
  selector: 'nxp-form-field',
  templateUrl: './form-field.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class NxpFormFieldComponent {
  @HostBinding('attr.aria-label') ariaLabel: string;
  @Input() required = false;
  @Input() type = 'text';
  @Input() config: IConfigurableOption<AbstractControl>;
  @Input() formGroup: UntypedFormGroup;
  @Input() theme: ThemePalette = 'primary';
  @Input() placeholder: string;
  @Input() isDisabled: boolean;
  @Input() showErrors: boolean;
  @Input() customIcon: string;
  @Input() customIconPosition: string;
  @Input() label: string;
  @Input() id: string;

  get formControlName(): string | null {
    return this.config?.control?.name ?? null;
  }

  get hasError(): boolean {
    return (
      !!this.config?.control?.errors &&
      Object.keys(this.config.control.errors).length !== 0
    );
  }

  get hasErrorTouchedAndDirty(): boolean {
    return (
      !!this.config?.control?.touched &&
      !!this.config?.control?.dirty &&
      this.hasError
    );
  }

  get formControl(): AbstractControl | null {
    return this.formGroup?.get(this.config?.control?.name) ?? null;
  }

  get isRequired(): boolean {
    return this.config?.control?.validator ? true : false;
  }

  get controlValue(): string | number | null {
    return this.config?.control?.value ?? null;
  }

  get hasValue(): boolean {
    return this.config?.control?.value ? true : false;
  }

  /**
   * @description
   * @param {Component} formControl - Form Control component
   */
  getFormControls(formControl: ComponentType<AbstractControl>) {
    const controls = [];
    const length = this.formGroup.controls.length;
    for (let i = 0; i < length; i++) {
      controls.push(formControl);
    }
    return controls;
  }

  getControlName(control: UntypedFormControl) {
    return control.name;
  }
}
